using UnityEngine; using UnityEngine.UI;
public sealed class PanelGraphic:MaskableGraphic { public Color Fill=Theme.Paper,Edge=Theme.Border,Highlight=Theme.White; public int Notch=3,Thickness=1; protected override void OnPopulateMesh(VertexHelper vh){vh.Clear(); var r=rectTransform.rect; float w=r.width,h=r.height,n=Notch; Vector2[] p={new(n,0),new(w-n,0),new(w, n),new(w,h-n),new(w-n,h),new(n,h),new(0,h-n),new(0,n)}; for(int i=0;i<p.Length;i++)vh.AddVert(p[i],Fill,Vector2.zero); for(int i=1;i<7;i++)vh.AddTriangle(0,i,i+1); if(Thickness>0){int b=vh.currentVertCount; foreach(var q in p)vh.AddVert(q,Edge,Vector2.zero); for(int i=0;i<8;i++){int j=(i+1)%8;vh.AddTriangle(b+i,b+j,i);vh.AddTriangle(b+j,j,i);}}}}
